-- Import the three legacy welcome-reward covers into the server-managed skin
-- library. New versions are created only for system campaigns whose current
-- version still has no configured skins, so operator customizations win.

WITH builtin_skins (
    name,
    description,
    alt_text,
    sha256,
    content
) AS (
    VALUES
        (
            'Starlink Explorer',
            'Built-in skin migrated from the legacy welcome reward.',
            'Starlink Explorer welcome reward scratch-card skin',
            '3edc56d44c36dea6ca8a485334d47be93956b4cce1275f5ad1110fa4264794a9',
            DECODE('', 'base64')
        ),
        (
            'Energy Gift',
            'Built-in skin migrated from the legacy welcome reward.',
            'Energy Gift welcome reward scratch-card skin',
            '5d0f5b9fbeccd24b47a54fcdda46341dc6212b33f107822c4bf3d8199fd9d171',
            DECODE('', 'base64')
        ),
        (
            'Lucky Passage',
            'Built-in skin migrated from the legacy welcome reward.',
            'Lucky Passage welcome reward scratch-card skin',
            '9a0788b03bdbf5d9c2c999a266f8cf0c40006f64c80115f7c89839754de7d8e5',
            DECODE('', 'base64')
        )
)
INSERT INTO reward_skins (
    name,
    description,
    alt_text,
    status,
    mime_type,
    width,
    height,
    byte_size,
    sha256,
    content
)
SELECT
    name,
    description,
    alt_text,
    'active',
    'image/webp',
    1320,
    500,
    OCTET_LENGTH(content),
    sha256,
    content
FROM builtin_skins
ON CONFLICT (sha256) DO NOTHING;

WITH locked_campaigns AS (
    SELECT id, current_version_id
    FROM reward_campaigns
    WHERE system_key IN ('system_welcome', 'system_surprise')
    FOR UPDATE
),
builtin_skin_set AS (
    SELECT
        JSONB_AGG(
            JSONB_BUILD_OBJECT('skin_id', id, 'weight', 1)
            ORDER BY CASE sha256
                WHEN '3edc56d44c36dea6ca8a485334d47be93956b4cce1275f5ad1110fa4264794a9' THEN 1
                WHEN '5d0f5b9fbeccd24b47a54fcdda46341dc6212b33f107822c4bf3d8199fd9d171' THEN 2
                WHEN '9a0788b03bdbf5d9c2c999a266f8cf0c40006f64c80115f7c89839754de7d8e5' THEN 3
            END
        ) AS weights,
        COUNT(*) AS skin_count
    FROM reward_skins
    WHERE status = 'active'
      AND sha256 IN (
          '3edc56d44c36dea6ca8a485334d47be93956b4cce1275f5ad1110fa4264794a9',
          '5d0f5b9fbeccd24b47a54fcdda46341dc6212b33f107822c4bf3d8199fd9d171',
          '9a0788b03bdbf5d9c2c999a266f8cf0c40006f64c80115f7c89839754de7d8e5'
      )
),
candidate_versions AS (
    SELECT
        campaign.id AS campaign_id,
        (
            SELECT COALESCE(MAX(version.version_number), 0) + 1
            FROM reward_campaign_versions version
            WHERE version.campaign_id = campaign.id
        ) AS version_number,
        JSONB_SET(current_version.config, '{skin_weights}', skins.weights, TRUE) AS config
    FROM locked_campaigns campaign
    JOIN reward_campaign_versions current_version
      ON current_version.campaign_id = campaign.id
     AND current_version.id = campaign.current_version_id
    CROSS JOIN builtin_skin_set skins
    WHERE skins.skin_count = 3
      AND CASE
          WHEN NOT (current_version.config ? 'skin_weights') THEN TRUE
          WHEN JSONB_TYPEOF(current_version.config->'skin_weights') <> 'array' THEN FALSE
          ELSE JSONB_ARRAY_LENGTH(current_version.config->'skin_weights') = 0
      END
),
new_versions AS (
    INSERT INTO reward_campaign_versions (
        campaign_id,
        version_number,
        config,
        config_hash,
        created_at
    )
    SELECT
        campaign_id,
        version_number,
        config,
        ENCODE(SHA256(CONVERT_TO(config::TEXT, 'UTF8')), 'hex'),
        NOW()
    FROM candidate_versions
    ON CONFLICT (campaign_id, version_number) DO NOTHING
    RETURNING id, campaign_id
)
UPDATE reward_campaigns campaign
SET current_version_id = version.id,
    updated_at = NOW()
FROM new_versions version
WHERE campaign.id = version.campaign_id;
